    23  // eslint-disable-next-line @typescript-eslint/no-unused-vars
    24  function EmojiPickerMenu({onEmojiSelected, activeEmoji}: EmojiPickerMenuProps, ref: ForwardedRef<BaseTextInputRef>) {
    25      const styles = useThemeStyles();
    26      const {windowWidth} = useWindowDimensions();
    27      const {shouldUseNarrowLayout} = useResponsiveLayout();
    28      const {translate} = useLocalize();
    29      const {singleExecution} = useSingleExecution();
    30      const {
    31          allEmojis,
    32          headerEmojis,
    33          headerRowIndices,
    34          filteredEmojis,
    35          headerIndices,
    36          setFilteredEmojis,
    37          setHeaderIndices,
    38          isListFiltered,
    39          suggestEmojis,
    40          preferredSkinTone,
    41          listStyle,
    42          emojiListRef,
    43      } = useEmojiPickerMenu();
    44      const StyleUtils = useStyleUtils();
    45
    46      /**
    47       * Filter the entire list of emojis to only emojis that have the search term in their keywords
    48       */
    49      const filterEmojis = lodashDebounce((searchTerm: string) => {
    50          const [normalizedSearchTerm, newFilteredEmojiList] = suggestEmojis(searchTerm);
    51
    52          if (emojiListRef.current) {
    53              emojiListRef.current.scrollToOffset({offset: 0, animated: false});
    54          }
    55
    56          if (normalizedSearchTerm === '') {
    57              setFilteredEmojis(allEmojis);
    58              setHeaderIndices(headerRowIndices);
    59
    60              return;
    61          }
    62
    63          setFilteredEmojis(newFilteredEmojiList ?? []);
    64          setHeaderIndices([]);
    65      }, 300);
    66
    67      const scrollToHeader = (headerIndex: number) => {
    68          const calculatedOffset = Math.floor(headerIndex / CONST.EMOJI_NUM_PER_ROW) * CONST.EMOJI_PICKER_HEADER_HEIGHT;
    69          emojiListRef.current?.scrollToOffset({offset: calculatedOffset, animated: true});
    70      };
    71
    72      /**
    73       * Given an emoji item object, render a component based on its type.
    74       * Items with the code "SPACER" return nothing and are used to fill rows up to 8
    75       * so that the sticky headers function properly.
    76       */
    77      const renderItem: ListRenderItem<EmojiUtils.EmojiPickerListItem> = useCallback(
    78          ({item, target}) => {
    79              const code = item.code;
    80              const types = 'types' in item ? item.types : undefined;
    81
    82              if ('spacer' in item && item.spacer) {
    83                  return null;
    84              }
    85
    86              if ('header' in item && item.header) {
