    90                      </View>
    91                  );
    92              }
    93
    94              const emojiCode = typeof preferredSkinTone === 'number' && types?.[preferredSkinTone] ? types?.[preferredSkinTone] : code;
    95              const shouldEmojiBeHighlighted = !!activeEmoji && EmojiUtils.getRemovedSkinToneEmoji(emojiCode) === EmojiUtils.getRemovedSkinToneEmoji(activeEmoji);
    96
    97              return (
    98                  <EmojiPickerMenuItem
    99                      onPress={singleExecution((emoji) => {
   100                          if (!('name' in item)) {
   101                              return;
   102                          }
   103                          onEmojiSelected(emoji, item);
   104                      })}
   105                      emoji={emojiCode}
   106                      isHighlighted={shouldEmojiBeHighlighted}
   107                  />
   108              );
   109          },
   110          [styles, windowWidth, preferredSkinTone, singleExecution, onEmojiSelected, translate, activeEmoji],
   111      );
   112
   113      return (
   114          <View style={[styles.emojiPickerContainer, StyleUtils.getEmojiPickerStyle(shouldUseNarrowLayout)]}>
   115              <View style={[styles.ph4, styles.pb1, styles.pt2]}>
   116                  <TextInput
   117                      label={translate('common.search')}
   118                      accessibilityLabel={translate('common.search')}
   119                      role={CONST.ROLE.PRESENTATION}
   120                      onChangeText={filterEmojis}
   121                      blurOnSubmit={filteredEmojis.length > 0}
   122                  />
   123              </View>
   124              <BaseEmojiPickerMenu
   125                  isFiltered={isListFiltered}
   126                  headerEmojis={headerEmojis}
   127                  scrollToHeader={scrollToHeader}
   128                  listWrapperStyle={[
   129                      listStyle,
   130                      {
   131                          width: Math.floor(windowWidth),
   132                      },
   133                  ]}
   134                  ref={emojiListRef}
   135                  data={filteredEmojis}
   136                  renderItem={renderItem}
   137                  extraData={[filteredEmojis, preferredSkinTone]}
   138                  stickyHeaderIndices={headerIndices}
   139                  alwaysBounceVertical={filteredEmojis.length !== 0}
   140              />
   141          </View>
   142      );
   143  }
