   145  EmojiPickerMenu.displayName = 'EmojiPickerMenu';
   146  export default React.forwardRef(EmojiPickerMenu);

1  import type {FlashList} from '@shopify/flash-list';
     2  import {useCallback, useEffect, useMemo, useRef, useState} from 'react';
     3  import emojis from '@assets/emojis';
     4  import {useFrequentlyUsedEmojis} from '@components/OnyxProvider';
     5  import useLocalize from '@hooks/useLocalize';
     6  import usePreferredEmojiSkinTone from '@hooks/usePreferredEmojiSkinTone';
     7  import useStyleUtils from '@hooks/useStyleUtils';
     8  import useWindowDimensions from '@hooks/useWindowDimensions';
     9  import * as EmojiUtils from '@libs/EmojiUtils';
    10
    11  const useEmojiPickerMenu = () => {
    12      const emojiListRef = useRef<FlashList<EmojiUtils.EmojiPickerListItem>>(null);
    13      const frequentlyUsedEmojis = useFrequentlyUsedEmojis();
    14      // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    15      const allEmojis = useMemo(() => EmojiUtils.mergeEmojisWithFrequentlyUsedEmojis(emojis), [frequentlyUsedEmojis]);
    16      const headerEmojis = useMemo(() => EmojiUtils.getHeaderEmojis(allEmojis), [allEmojis]);
    17      const headerRowIndices = useMemo(() => headerEmojis.map((headerEmoji) => headerEmoji.index), [headerEmojis]);
    18      const spacersIndexes = useMemo(() => EmojiUtils.getSpacersIndexes(allEmojis), [allEmojis]);
    19      const [filteredEmojis, setFilteredEmojis] = useState<EmojiUtils.EmojiPickerList>(allEmojis);
    20      const [headerIndices, setHeaderIndices] = useState(headerRowIndices);
    21      const isListFiltered = allEmojis.length !== filteredEmojis.length;
    22      const {preferredLocale} = useLocalize();
    23      const [preferredSkinTone] = usePreferredEmojiSkinTone();
    24      const {windowHeight} = useWindowDimensions();
    25      const StyleUtils = useStyleUtils();
    26      /**
    27       * At EmojiPicker has set innerContainerStyle with maxHeight: '95%' by styles.popoverInnerContainer
    28       * to avoid the list style to be cut off due to the list height being larger than the container height
    29       * so we need to calculate listStyle based on the height of the window and innerContainerStyle at the EmojiPicker
    30       */
    31      const listStyle = StyleUtils.getEmojiPickerListHeight(isListFiltered, windowHeight * 0.95);
    32
    33      useEffect(() => {
    34          setFilteredEmojis(allEmojis);
    35      }, [allEmojis]);
    36
    37      useEffect(() => {
    38          setHeaderIndices(headerRowIndices);
    39      }, [headerRowIndices]);
    40
    41      /**
    42       * Suggest emojis based on the search term
    43       */
    44      const suggestEmojis = useCallback(
    45          (searchTerm: string) => {
    46              const normalizedSearchTerm = searchTerm.toLowerCase().trim().replaceAll(':', '');
    47              const emojisSuggestions = EmojiUtils.suggestEmojis(`:${normalizedSearchTerm}`, preferredLocale, allEmojis.length);
    48
    49              return [normalizedSearchTerm, emojisSuggestions] as const;
    50          },
    51          [allEmojis, preferredLocale],
    52      );
    53
    54      return {
    55          allEmojis,
    56          headerEmojis,
    57          headerRowIndices,
    58          filteredEmojis,
    59          headerIndices,
    60          setFilteredEmojis,
    61          setHeaderIndices,
    62          isListFiltered,
    63          suggestEmojis,
    64          preferredSkinTone,
    65          listStyle,
    66          emojiListRef,
    67          spacersIndexes,
    68      };
    69  };
    70
    71  export default useEmojiPickerMenu;

1  import {Str} from 'expensify-common';
     2  import Onyx from 'react-native-onyx';
     3  import type {OnyxEntry} from 'react-native-onyx';
     4  import * as Emojis from '@assets/emojis';
     5  import type {Emoji, HeaderEmoji, PickerEmojis} from '@assets/emojis/types';
     6  import CONST from '@src/CONST';
     7  import ONYXKEYS from '@src/ONYXKEYS';
     8  import type {FrequentlyUsedEmoji, Locale} from '@src/types/onyx';
     9  import type {ReportActionReaction, UsersReactions} from '@src/types/onyx/ReportActionReactions';
    10  import type IconAsset from '@src/types/utils/IconAsset';
    11  import type EmojiTrie from './EmojiTrie';
    12  import type {SupportedLanguage} from './EmojiTrie';
    13  import memoize from './memoize';
    14
    15  type HeaderIndice = {code: string; index: number; icon: IconAsset};
    16  type EmojiSpacer = {code: string; spacer: boolean};
    17  type EmojiPickerListItem = EmojiSpacer | Emoji | HeaderEmoji;
    18  type EmojiPickerList = EmojiPickerListItem[];
    19  type ReplacedEmoji = {text: string; emojis: Emoji[]; cursorPosition?: number};
    20  type EmojiTrieModule = {default: typeof EmojiTrie};
    21
    22  const findEmojiByName = (name: string): Emoji => Emojis.emojiNameTable[name];
    23
    24  const findEmojiByCode = (code: string): Emoji => Emojis.emojiCodeTableWithSkinTones[code];
    25
    26  let frequentlyUsedEmojis: FrequentlyUsedEmoji[] = [];
    27  Onyx.connect({
    28      key: ONYXKEYS.FREQUENTLY_USED_EMOJIS,
    29      callback: (val) => {
    30          if (!val) {
    31              return;
    32          }
    33          frequentlyUsedEmojis =
    34              val
    35                  ?.map((item) => {
    36                      let emoji = item;
    37                      if (!item.code) {
    38                          emoji = {...emoji, ...findEmojiByName(item.name)};
    39                      }
    40                      if (!item.name) {
    41                          emoji = {...emoji, ...findEmojiByCode(item.code)};
    42                      }
    43                      const emojiWithSkinTones = Emojis.emojiCodeTableWithSkinTones[emoji.code];
    44                      return {...emojiWithSkinTones, count: item.count, lastUpdatedAt: item.lastUpdatedAt};
    45                  })
    46                  .filter((emoji): emoji is FrequentlyUsedEmoji => !!emoji) ?? [];
    47
    48          // On AddComment API response, each variant of the same emoji (with different skin tones) is
    49          // treated as a separate entry due to unique emoji codes for each variant.
    50          // So merge duplicate emojis, sum their counts, and use the latest lastUpdatedAt timestamp, then sort accordingly.
    51          const frequentlyUsedEmojiCodesToObjects = new Map<string, FrequentlyUsedEmoji>();
    52          frequentlyUsedEmojis.forEach((emoji) => {
    53              const existingEmoji = frequentlyUsedEmojiCodesToObjects.get(emoji.code);
    54              if (existingEmoji) {
    55                  existingEmoji.count += emoji.count;
    56                  existingEmoji.lastUpdatedAt = Math.max(existingEmoji.lastUpdatedAt, emoji.lastUpdatedAt);
    57              } else {
    58                  frequentlyUsedEmojiCodesToObjects.set(emoji.code, emoji);
    59              }
    60          });
    61          frequentlyUsedEmojis = Array.from(frequentlyUsedEmojiCodesToObjects.values()).sort((a, b) => {
    62              if (a.count !== b.count) {
    63                  return b.count - a.count;
    64              }
    65              return b.lastUpdatedAt - a.lastUpdatedAt;
    66          });
    67      },
    68  });
    69
    70  const getEmojiName = (emoji: Emoji, lang: Locale = CONST.LOCALES.DEFAULT): string => {
    71      if (!emoji) {
    72          return '';
    73      }
    74      if (lang === CONST.LOCALES.DEFAULT) {
    75          return emoji.name;
    76      }
    77
    78      return Emojis.localeEmojis?.[lang]?.[emoji.code]?.name ?? '';
    79  };
    80
    81  /**
    82   * Given an English emoji name, get its localized version
    83   */
    84  const getLocalizedEmojiName = (name: string, lang: OnyxEntry<Locale>): string => {
    85      if (lang === CONST.LOCALES.DEFAULT) {
    86          return name;
    87      }
    88
    89      const emojiCode = Emojis.emojiNameTable[name]?.code ?? '';
    90      return (lang && Emojis.localeEmojis[lang]?.[emojiCode]?.name) ?? '';
    91  };
    92
    93  /**
    94   * Get the unicode code of an emoji in base 16.
    95   */
    96  const getEmojiUnicode = memoize(
    97      (input: string) => {
    98          if (input.length === 0) {
    99              return '';
   100          }
   101
   102          if (input.length === 1) {
   103              return input
   104                  .charCodeAt(0)
   105                  .toString()
   106                  .split(' ')
   107                  .map((val) => parseInt(val, 10).toString(16))
   108                  .join(' ');
   109          }
   110
   111          const pairs = [];
   112
   113          // Some Emojis in UTF-16 are stored as a pair of 2 Unicode characters (e.g. Flags)
   114          // The first char is generally between the range U+D800 to U+DBFF called High surrogate
   115          // & the second char between the range U+DC00 to U+DFFF called low surrogate
   116          // More info in the following links:
   117          // 1. https://docs.microsoft.com/en-us/windows/win32/intl/surrogates-and-supplementary-characters
   118          // 2. https://thekevinscott.com/emojis-in-javascript/
   119          for (let i = 0; i < input.length; i++) {
   120              if (input.charCodeAt(i) >= 0xd800 && input.charCodeAt(i) <= 0xdbff) {
   121                  // high surrogate
   122                  if (input.charCodeAt(i + 1) >= 0xdc00 && input.charCodeAt(i + 1) <= 0xdfff) {
   123                      // low surrogate
   124                      pairs.push((input.charCodeAt(i) - 0xd800) * 0x400 + (input.charCodeAt(i + 1) - 0xdc00) + 0x10000);
   125                  }
   126              } else if (input.charCodeAt(i) < 0xd800 || input.charCodeAt(i) > 0xdfff) {
   127                  // modifiers and joiners
   128                  pairs.push(input.charCodeAt(i));
   129              }
   130          }
   131          return pairs.map((val) => parseInt(String(val), 10).toString(16)).join(' ');
   132      },
   133      {monitoringName: 'getEmojiUnicode'},
   134  );
   135
   136  /**
   137   * Function to remove Skin Tone and utf16 surrogates from Emoji
   138   */
   139  function trimEmojiUnicode(emojiCode: string): string {
   140      return emojiCode.replace(/(fe0f|1f3fb|1f3fc|1f3fd|1f3fe|1f3ff)$/, '').trim();
   141  }
   142
   143  /**
   144   * Validates first character is emoji in text string
   145   */
   146  function isFirstLetterEmoji(message: string): boolean {
   147      const trimmedMessage = Str.replaceAll(message.replace(/ /g, ''), '\n', '');
   148      const match = trimmedMessage.match(CONST.REGEX.EMOJIS);
   149
   150      if (!match) {
   151          return false;
   152      }
   153
   154      return trimmedMessage.startsWith(match[0]);
   155  }
   156
   157  /**
   158   * Validates that this message contains only emojis
   159   */
   160  function containsOnlyEmojis(message: string): boolean {
   161      const trimmedMessage = Str.replaceAll(message.replace(/ /g, ''), '\n', '');
   162      const match = trimmedMessage.match(CONST.REGEX.EMOJIS);
   163
   164      if (!match) {
   165          return false;
   166      }
   167
   168      const codes = [];
   169      match.map((emoji) =>
   170          getEmojiUnicode(emoji)
   171              .split(' ')
   172              .map((code) => {
   173                  if (!(CONST.INVISIBLE_CODEPOINTS as readonly string[]).includes(code)) {
   174                      codes.push(code);
   175                  }
   176                  return code;
   177              }),
   178      );
   179
   180      // Emojis are stored as multiple characters, so we're using spread operator
   181      // to iterate over the actual emojis, not just characters that compose them
   182      const messageCodes = [...trimmedMessage]
   183          .map((char) => getEmojiUnicode(char))
   184          .filter((string) => string.length > 0 && !(CONST.INVISIBLE_CODEPOINTS as readonly string[]).includes(string));
   185      return codes.length === messageCodes.length;
   186  }
   187
   188  /**
   189   * Get the header emojis with their code, icon and index
   190   */
   191  function getHeaderEmojis(emojis: EmojiPickerList): HeaderIndice[] {
   192      const headerIndices: HeaderIndice[] = [];
   193      emojis.forEach((emoji, index) => {
   194          if (!('header' in emoji)) {
   195              return;
   196          }
   197          headerIndices.push({code: emoji.code, index, icon: emoji.icon});
   198      });
   199      return headerIndices;
   200  }
   201
   202  /**
   203   * Get number of empty spaces to be filled to get equal emojis for every row
   204   */
   205  function getDynamicSpacing(emojiCount: number, suffix: number): EmojiSpacer[] {
   206      const spacerEmojis = [];
   207      let modLength = CONST.EMOJI_NUM_PER_ROW - (emojiCount % CONST.EMOJI_NUM_PER_ROW);
   208
   209      // Empty spaces is pushed if the given row has less than eight emojis
   210      while (modLength > 0 && modLength < CONST.EMOJI_NUM_PER_ROW) {
   211          spacerEmojis.push({
   212              code: `${CONST.EMOJI_SPACER}_${suffix}_${modLength}`,
   213              spacer: true,
   214          });
   215          modLength -= 1;
   216      }
   217      return spacerEmojis;
   218  }
   219
   220  /**
   221   * Add dynamic spaces to emoji categories
   222   */
   223  function addSpacesToEmojiCategories(emojis: PickerEmojis): EmojiPickerList {
   224      let updatedEmojis: EmojiPickerList = [];
   225      emojis.forEach((emoji, index) => {
   226          if (emoji && typeof emoji === 'object' && 'header' in emoji) {
   227              updatedEmojis = updatedEmojis.concat(getDynamicSpacing(updatedEmojis.length, index), [emoji], getDynamicSpacing(1, index));
   228              return;
   229          }
   230          updatedEmojis.push(emoji);
   231      });
   232      return updatedEmojis;
   233  }
   234
   235  /**
   236   * Get a merged array with frequently used emojis
   237   */
   238  function mergeEmojisWithFrequentlyUsedEmojis(emojis: PickerEmojis): EmojiPickerList {
   239      if (frequentlyUsedEmojis.length === 0) {
   240          return addSpacesToEmojiCategories(emojis);
   241      }
   242
   243      const formattedFrequentlyUsedEmojis = frequentlyUsedEmojis.map((frequentlyUsedEmoji: Emoji): Emoji => {
   244          // Frequently used emojis in the old format will have name/types/code stored with them
   245          // The back-end may not always have both, so we'll need to fill them in.
   246          if (!('code' in (frequentlyUsedEmoji as FrequentlyUsedEmoji))) {
   247              return findEmojiByName(frequentlyUsedEmoji.name);
   248          }
   249          if (!('name' in (frequentlyUsedEmoji as FrequentlyUsedEmoji))) {
   250              return findEmojiByCode(frequentlyUsedEmoji.code);
   251          }
   252
   253          return frequentlyUsedEmoji;
   254      });
   255
   256      const mergedEmojis = [Emojis.categoryFrequentlyUsed, ...formattedFrequentlyUsedEmojis, ...emojis];
   257      return addSpacesToEmojiCategories(mergedEmojis);
   258  }
   259
   260  /**
   261   * Given an emoji item object, return an emoji code based on its type.
   262   */
   263  const getEmojiCodeWithSkinColor = (item: Emoji, preferredSkinToneIndex: OnyxEntry<number | string>): string => {
   264      const {code, types} = item;
   265
   266      if (typeof preferredSkinToneIndex === 'number' && types?.[preferredSkinToneIndex]) {
   267          return types[preferredSkinToneIndex];
   268      }
   269
   270      return code;
   271  };
   272
   273  /**
   274   * Extracts emojis from a given text.
   275   *
   276   * @param text - The text to extract emojis from.
   277   * @returns An array of emoji codes.
   278   */
   279  function extractEmojis(text: string): Emoji[] {
   280      if (!text) {
   281          return [];
   282      }
   283
   284      // Parse Emojis including skin tones - Eg: ['👩🏻', '👩🏻', '👩🏼', '👩🏻', '👩🏼', '👩']
   285      const parsedEmojis = text.match(CONST.REGEX.EMOJIS);
   286
   287      if (!parsedEmojis) {
   288          return [];
   289      }
   290
   291      const emojis: Emoji[] = [];
   292
   293      // Text can contain similar emojis as well as their skin tone variants. Create a Set to remove duplicate emojis from the search.
   294
   295      for (const character of parsedEmojis) {
   296          const emoji = Emojis.emojiCodeTableWithSkinTones[character];
   297          if (emoji) {
   298              emojis.push(emoji);
   299          }
   300      }
   301
   302      return emojis;
   303  }
   304
   305  /**
   306   * Take the current emojis and the former emojis and return the emojis that were added, if we add an already existing emoji, we also return it
   307   * @param currentEmojis The array of current emojis
   308   * @param formerEmojis The array of former emojis
   309   * @returns The array of added emojis
   310   */
   311  function getAddedEmojis(currentEmojis: Emoji[], formerEmojis: Emoji[]): Emoji[] {
