   336      let newText = text;
   337      const emojis: Emoji[] = [];
   338      const emojiData = text.match(CONST.REGEX.EMOJI_NAME);
   339      if (!emojiData || emojiData.length === 0) {
   340          return {text: newText, emojis};
   341      }
   342
   343      let cursorPosition;
   344
   345      for (const emoji of emojiData) {
   346          const name = emoji.slice(1, -1);
   347          let checkEmoji = trie.search(name);
   348          // If the user has selected a language other than English, and the emoji doesn't exist in that language,
   349          // we will check if the emoji exists in English.
