   405  function suggestEmojis(text: string, lang: Locale, limit: number = CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS): Emoji[] | undefined {
   406      // emojisTrie is importing the emoji JSON file on the app starting and we want to avoid it
   407      const emojisTrie = require<EmojiTrieModule>('./EmojiTrie').default;
