   419      const matching: Emoji[] = [];
   420      const nodes = trie.getAllMatchingWords(emojiData[0].toLowerCase().slice(1), limit);
   421      for (const node of nodes) {
   422          if (node.metaData?.code && !matching.find((obj) => obj.name === node.name)) {
   423              if (matching.length === limit) {
